package ir.matab.desk;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.io.*;
import java.time.LocalDate;
import java.text.Normalizer;
import java.util.*;

final class LocalDatabase extends SQLiteOpenHelper {
 private final Context context; private final JSONObject years;
 private static final String[] KINDS={"services","products","areas","methods","doctors"};
 LocalDatabase(Context c)throws Exception{super(c,"matab.sqlite3",null,4);context=c;years=new JSONObject(readAsset(c,"calendar-years.json"));}
 static String readAsset(Context c,String name)throws IOException{try(InputStream in=c.getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 @Override public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);}
 @Override public void onCreate(SQLiteDatabase db){try{for(String statement:readAsset(context,"schema.sql").split(";"))if(!statement.trim().isEmpty())db.execSQL(statement);}catch(Exception e){throw new IllegalStateException(e);}}
 @Override public void onUpgrade(SQLiteDatabase db,int a,int b){if(a<2){db.execSQL("ALTER TABLE catalogs ADD COLUMN fee_bps INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE records ADD COLUMN cost_reviewed INTEGER NOT NULL DEFAULT 0");db.execSQL("ALTER TABLE records ADD COLUMN divisor_milli INTEGER NOT NULL DEFAULT 2000");db.execSQL("ALTER TABLE payments ADD COLUMN fee_bps INTEGER");}if(a<3){db.execSQL("CREATE TABLE IF NOT EXISTS patients(id TEXT PRIMARY KEY,created INTEGER NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,mobile TEXT NOT NULL,legacy_name TEXT NOT NULL)");db.execSQL("ALTER TABLE records ADD COLUMN patient_id TEXT REFERENCES patients(id)");db.execSQL("ALTER TABLE records ADD COLUMN details_json TEXT NOT NULL DEFAULT '{}'");}onCreate(db);}

 @Override public void onOpen(SQLiteDatabase db){super.onOpen(db);try{HistorySupport.initialize(db,context);}catch(Exception e){throw new IllegalStateException(e);}}
 private static ContentValues values(Object... entries){ContentValues v=new ContentValues();for(int i=0;i<entries.length;i+=2){String k=(String)entries[i];Object x=entries[i+1];if(x==null||x==JSONObject.NULL)v.putNull(k);else if(x instanceof Boolean)v.put(k,((Boolean)x)?1:0);else if(x instanceof Float||x instanceof Double)v.put(k,((Number)x).doubleValue());else if(x instanceof Number)v.put(k,((Number)x).longValue());else v.put(k,x.toString());}return v;}
 private static String str(Cursor c,String k){return c.getString(c.getColumnIndexOrThrow(k));}
 private static long lng(Cursor c,String k){return c.getLong(c.getColumnIndexOrThrow(k));}
 private static String meta(SQLiteDatabase db,String key){try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key=?",new String[]{key})){return c.moveToFirst()?c.getString(0):null;}}
 synchronized JSONObject read()throws Exception{
  SQLiteDatabase db=getReadableDatabase();db.beginTransaction();try{
   long revision=Long.parseLong(meta(db,"revision"));JSONObject out=new JSONObject().put("revision",revision);String clinic=meta(db,"clinic");if(clinic==null)return out.put("state",JSONObject.NULL);
   JSONObject state=new JSONObject().put("version",meta(db,"stateVersion")==null?3:Integer.parseInt(meta(db,"stateVersion"))).put("clinic",clinic),catalogs=new JSONObject();
   for(String kind:KINDS){JSONArray list=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM catalogs WHERE kind=? ORDER BY sort_order",new String[]{kind})){while(c.moveToNext()){JSONObject row=new JSONObject().put("id",str(c,"id")).put("name",str(c,"name")).put("active",lng(c,"active")==1);if(kind.equals("methods"))row.put("feeBps",lng(c,"fee_bps"));list.put(row);}}catalogs.put(kind,list);}
   JSONArray records=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM records ORDER BY created",null)){while(c.moveToNext()){
    JSONObject r=new JSONObject();for(String k:new String[]{"id","patient","service","product","area","unit","note"})r.put(k,str(c,k));for(String k:new String[]{"created","price","amount"})r.put(k,lng(c,k));r.put("date",str(c,"service_date")).put("volume",c.getDouble(c.getColumnIndexOrThrow("volume")));
    JSONArray payments=new JSONArray();long paid=0;try(Cursor p=db.rawQuery("SELECT * FROM payments WHERE record_id=? ORDER BY sort_order",new String[]{str(c,"id")})){while(p.moveToNext()){JSONObject row=new JSONObject();for(String k:new String[]{"id","method","stage","note"})row.put(k,str(p,k));row.put("amount",lng(p,"amount")).put("methodLabel",str(p,"method_label")).put("date",p.isNull(p.getColumnIndexOrThrow("payment_date"))?JSONObject.NULL:str(p,"payment_date")).put("legacy",lng(p,"legacy")==1).put("feeBps",p.isNull(p.getColumnIndexOrThrow("fee_bps"))?JSONObject.NULL:lng(p,"fee_bps"));paid+=lng(p,"amount");payments.put(row);}}
    JSONArray consumed=new JSONArray();try(Cursor cns=db.rawQuery("SELECT * FROM consumptions WHERE record_id=? ORDER BY sort_order",new String[]{r.getString("id")})){while(cns.moveToNext())consumed.put(new JSONObject().put("id",str(cns,"id")).put("receiptId",str(cns,"receipt_id")).put("quantityMilli",lng(cns,"quantity_milli")));}if(state.getInt("version")>=5){JSONObject details=new JSONObject(str(c,"details_json"));java.util.Iterator<String> keys=details.keys();while(keys.hasNext()){String key=keys.next();r.put(key,details.get(key));}r.put("patientId",c.isNull(c.getColumnIndexOrThrow("patient_id"))?JSONObject.NULL:str(c,"patient_id"));}r.put("costReviewed",lng(c,"cost_reviewed")==1).put("divisorMilli",lng(c,"divisor_milli")).put("consumptions",consumed).put("payments",payments).put("paid",paid);records.put(r);
   }}
   JSONArray receipts=new JSONArray();try(Cursor rc=db.rawQuery("SELECT * FROM receipts ORDER BY created",null)){while(rc.moveToNext()){JSONObject rr=new JSONObject();for(String[] pair:new String[][]{{"id","id"},{"date","receipt_date"},{"productId","product_id"},{"productLabel","product_label"},{"packUnit","pack_unit"},{"baseUnit","base_unit"},{"note","note"}})rr.put(pair[0],str(rc,pair[1]));for(String[] pair:new String[][]{{"created","created"},{"quantityMilli","quantity_milli"},{"contentsMilli","contents_milli"},{"unitPrice","unit_price"},{"receivedMilli","received_milli"},{"totalCost","total_cost"}})rr.put(pair[0],lng(rc,pair[1]));try(Cursor profile=db.rawQuery("SELECT doctor_id,doctor_label FROM receipt_profiles WHERE receipt_id=?",new String[]{rr.getString("id")})){if(profile.moveToFirst())rr.put("doctorId",profile.getString(0)).put("doctorLabel",profile.getString(1));}receipts.put(rr);}}JSONArray patients=new JSONArray();try(Cursor pc=db.rawQuery("SELECT * FROM patients ORDER BY created,id",null)){while(pc.moveToNext())patients.put(new JSONObject().put("id",str(pc,"id")).put("created",lng(pc,"created")).put("firstName",str(pc,"first_name")).put("lastName",str(pc,"last_name")).put("mobile",str(pc,"mobile")).put("legacyName",str(pc,"legacy_name")));}state.put("patients",patients);String settings=meta(db,"financeSettings");state.put("receipts",receipts).put("settings",settings==null?new JSONObject().put("divisorMilli",2000):new JSONObject(settings));String backup=meta(db,"lastBackup");state.put("catalogs",catalogs).put("records",records).put("lastBackup",backup==null||backup.equals("null")?JSONObject.NULL:new JSONTokener(backup).nextValue());return out.put("state",state);
  }finally{db.endTransaction();}
 }
 private static void require(boolean b)throws Exception{if(!b)throw new Exception("اطلاعات معتبر نیست.");}
 private static String text(JSONObject o,String key,int max,boolean required)throws Exception{Object raw=o.get(key);require(raw instanceof String);String s=(String)raw;require(s.length()<=max&&(!required||!s.trim().isEmpty()));return s;}
 private static long integer(JSONObject o,String key,long max)throws Exception{Object raw=o.get(key);require(raw instanceof Number);Number n=(Number)raw;long v=n.longValue();require(v>=0&&v<=max&&n.doubleValue()==(double)v);return v;}
 private boolean dateOK(String s){try{if(!s.matches("[0-9]{4}/[0-9]{2}/[0-9]{2}"))return false;String[] p=s.split("/");int y=Integer.parseInt(p[0]),m=Integer.parseInt(p[1]),d=Integer.parseInt(p[2]);if(y<1300||y>1500||m<1||m>12)return false;long days=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(years.getString(""+y)),LocalDate.parse(years.getString(""+(y+1))));return d>=1&&d<=(m<=6?31:m<12||days==366?30:29);}catch(Exception e){return false;}}
 private static String norm(String s){return Normalizer.normalize(s,Normalizer.Form.NFKC).replace('ي','ی').replace('ك','ک').replace('\u200c',' ').replace('\u200d',' ').trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);}
 private void validate(JSONObject s)throws Exception{
  require(s.getInt("version")==5);text(s,"clinic",80,true);JSONObject cats=s.getJSONObject("catalogs");Set<String> methodIds=new HashSet<>();
  for(String kind:KINDS){JSONArray a=cats.getJSONArray(kind);require(a.length()<=1000);Set<String> ids=new HashSet<>(),names=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);String id=text(c,"id",100,true),name=text(c,"name",80,true);require(!id.equals("unknown")&&ids.add(id)&&names.add(norm(name))&&c.get("active") instanceof Boolean);if(kind.equals("methods"))methodIds.add(id);}}
  JSONArray records=s.getJSONArray("records");require(records.length()<=100000);Set<String> ids=new HashSet<>();long total=0;
  for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);require(ids.add(text(r,"id",100,true)));integer(r,"created",9007199254740991L);require(dateOK(text(r,"date",10,true)));integer(r,"price",1000000000000L);long amount=integer(r,"amount",1000000000000L);total+=amount;require(total<=9007199254740991L);
   for(String k:new String[]{"patient","service","product","area"})text(r,k,k.equals("patient")?161:80,k.equals("service")||k.equals("area"));text(r,"note",500,false);require(Arrays.asList("cc","unit","session").contains(r.getString("unit")));double volume=r.getDouble("volume");require(Double.isFinite(volume)&&volume>0&&volume<=100000);
   JSONArray ps=r.getJSONArray("payments");require(ps.length()<=1000);Set<String> pids=new HashSet<>();long paid=0;
   for(int j=0;j<ps.length();j++){JSONObject p=ps.getJSONObject(j);require(pids.add(text(p,"id",120,true)));long value=integer(p,"amount",1000000000000L);require(value>0);paid+=value;require(paid<=amount);String method=text(p,"method",100,true),stage=p.getString("stage");text(p,"methodLabel",80,true);text(p,"note",200,false);require(p.get("legacy") instanceof Boolean);boolean legacy=p.getBoolean("legacy");require((p.isNull("date")&&legacy)||(!p.isNull("date")&&dateOK(p.getString("date"))));require(methodIds.contains(method)||(legacy&&method.equals("unknown")));require(Arrays.asList("deposit","payment","settlement","legacy").contains(stage));require(legacy||(!method.equals("unknown")&&!stage.equals("legacy")));}
  }
  require(s.isNull("lastBackup")||dateOK(s.getString("lastBackup")));ProfileValidator.validate(s);FinanceValidator.validate(s,this::dateOK);
 }
 synchronized JSONObject write(JSONObject request)throws Exception{
  JSONObject s=request.getJSONObject("state");validate(s);String operation=request.optString("operation","save");if(!java.util.Arrays.asList("save","restore","restore-settings").contains(operation))throw new Exception("عملیات معتبر نیست.");JSONArray imported=request.optJSONArray("history");HistorySupport.validateHistory(imported);if(imported!=null&&!operation.equals("restore"))throw new Exception("تاریخچه فقط در بازیابی کامل وارد می‌شود.");long expected=integer(request,"revision",9007199254740991L);JSONObject previous=read().optJSONObject("state");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{
   long current=Long.parseLong(meta(db,"revision"));if(current!=expected)throw new Exception("اطلاعات تغییر کرده؛ برنامه را دوباره باز کنید.");
   db.delete("receipt_profiles",null,null);db.delete("consumptions",null,null);db.delete("receipts",null,null);db.delete("payments",null,null);db.delete("records",null,null);db.delete("patients",null,null);db.delete("catalogs",null,null);
   JSONObject cats=s.getJSONObject("catalogs");for(String kind:KINDS){JSONArray a=cats.getJSONArray(kind);for(int i=0;i<a.length();i++){JSONObject c=a.getJSONObject(i);db.insertOrThrow("catalogs",null,values("kind",kind,"id",c.getString("id"),"name",c.getString("name"),"active",c.getBoolean("active"),"sort_order",i,"fee_bps",kind.equals("methods")?c.getInt("feeBps"):0));}}
   JSONArray patients=s.getJSONArray("patients");for(int i=0;i<patients.length();i++){JSONObject p=patients.getJSONObject(i);db.insertOrThrow("patients",null,values("id",p.getString("id"),"created",p.getLong("created"),"first_name",p.getString("firstName"),"last_name",p.getString("lastName"),"mobile",p.getString("mobile"),"legacy_name",p.getString("legacyName")));}
   JSONArray receipts=s.getJSONArray("receipts");for(int i=0;i<receipts.length();i++){JSONObject r=receipts.getJSONObject(i);db.insertOrThrow("receipts",null,values("id",r.getString("id"),"created",r.getLong("created"),"receipt_date",r.getString("date"),"product_id",r.getString("productId"),"product_label",r.getString("productLabel"),"quantity_milli",r.getLong("quantityMilli"),"pack_unit",r.getString("packUnit"),"contents_milli",r.getLong("contentsMilli"),"base_unit",r.getString("baseUnit"),"unit_price",r.getLong("unitPrice"),"received_milli",r.getLong("receivedMilli"),"total_cost",r.getLong("totalCost"),"note",r.getString("note")));}
   for(int k=0;k<receipts.length();k++){JSONObject r=receipts.getJSONObject(k);if(!r.isNull("doctorId"))db.insertOrThrow("receipt_profiles",null,values("receipt_id",r.getString("id"),"doctor_id",r.getString("doctorId"),"doctor_label",r.getString("doctorLabel")));}
   JSONArray records=s.getJSONArray("records");for(int i=0;i<records.length();i++){JSONObject r=records.getJSONObject(i);ContentValues row=new ContentValues();for(String k:new String[]{"id","patient","service","product","area","unit","note"})row.put(k,r.getString(k));for(String k:new String[]{"created","price","amount"})row.put(k,r.getLong(k));row.put("volume",r.getDouble("volume"));row.put("service_date",r.getString("date"));row.put("cost_reviewed",r.getBoolean("costReviewed")?1:0);row.put("divisor_milli",r.getLong("divisorMilli"));JSONObject details=new JSONObject();for(String key:new String[]{"firstName","lastName","mobile","legacyName","doctorId","doctorLabel","shareMode","doctorBps"})details.put(key,r.get(key));row.put("details_json",details.toString());if(r.isNull("patientId"))row.putNull("patient_id");else row.put("patient_id",r.getString("patientId"));db.insertOrThrow("records",null,row);
    JSONArray ps=r.getJSONArray("payments");for(int j=0;j<ps.length();j++){JSONObject p=ps.getJSONObject(j);db.insertOrThrow("payments",null,values("record_id",r.getString("id"),"id",p.getString("id"),"amount",p.getLong("amount"),"payment_date",p.opt("date"),"method",p.getString("method"),"method_label",p.getString("methodLabel"),"stage",p.getString("stage"),"note",p.getString("note"),"legacy",p.getBoolean("legacy"),"sort_order",j,"fee_bps",p.opt("feeBps")));}
    JSONArray cs=r.getJSONArray("consumptions");for(int j=0;j<cs.length();j++){JSONObject c=cs.getJSONObject(j);db.insertOrThrow("consumptions",null,values("record_id",r.getString("id"),"id",c.getString("id"),"receipt_id",c.getString("receiptId"),"quantity_milli",c.getLong("quantityMilli"),"sort_order",j));}
   }
   db.insertWithOnConflict("meta",null,values("key","stateVersion","value","5"),SQLiteDatabase.CONFLICT_REPLACE);db.insertWithOnConflict("meta",null,values("key","financeSettings","value",s.getJSONObject("settings").toString()),SQLiteDatabase.CONFLICT_REPLACE);
   db.insertWithOnConflict("meta",null,values("key","clinic","value",s.getString("clinic")),SQLiteDatabase.CONFLICT_REPLACE);db.insertWithOnConflict("meta",null,values("key","lastBackup","value",s.opt("lastBackup")==JSONObject.NULL?"null":JSONObject.quote(s.getString("lastBackup"))),SQLiteDatabase.CONFLICT_REPLACE);db.insertWithOnConflict("meta",null,values("key","revision","value",""+(current+1)),SQLiteDatabase.CONFLICT_REPLACE);
   HistorySupport.importRows(db,imported);HistorySupport.changes(db,previous,s,operation);db.setTransactionSuccessful();return new JSONObject().put("revision",current+1);
  }finally{db.endTransaction();}
 }
 synchronized JSONObject history(JSONObject filters)throws Exception{return HistorySupport.history(getReadableDatabase(),filters,false);}
 synchronized JSONObject releases()throws Exception{return HistorySupport.releaseHistory(getReadableDatabase(),context);}
 synchronized JSONObject backup(String scope)throws Exception{JSONObject state=read().getJSONObject("state");if(scope.equals("settings"))return new JSONObject().put("format","matab-settings").put("formatVersion",1).put("clinic",state.getString("clinic")).put("settings",state.getJSONObject("settings")).put("catalogs",state.getJSONObject("catalogs"));if(!scope.equals("full"))throw new Exception("نوع پشتیبان معتبر نیست.");return new JSONObject().put("format","matab-backup").put("formatVersion",1).put("state",state).put("history",HistorySupport.history(getReadableDatabase(),new JSONObject(),true).getJSONArray("rows")).put("releases",releases().getJSONArray("releases"));}
 synchronized void backupEvent(String scope,String destination)throws Exception{if(!java.util.Arrays.asList("full","settings").contains(scope)||!java.util.Arrays.asList("local","drive").contains(destination))throw new Exception("رویداد معتبر نیست.");HistorySupport.add(getWritableDatabase(),"export","backup","آماده‌سازی یا ذخیره فایل پشتیبان "+(scope.equals("full")?"کامل":"تنظیمات"),"",new JSONObject().put("scope",scope).put("destination",destination),null,false,null);}

}
